      'AC1: every primary upload step carries an id the retry references',
      () {
        for (final step in primaries) {
          expect(
            step['id'],
            isA<String>(),
            reason:
                'primary upload step "${step['name'] ?? step['uses']}" '
                'lost its id — the gh-1412 retry keys on '
                'steps.<id>.outcome',
          );
        }
      },
    );

