      for (final step in steps)
        if (isUploadStep(step) && isRetryStep(step)) step,
    ];

    test('the leg carries the two evidence uploads and their retries', () {
      expect(
        primaries,
        hasLength(2),
        reason:
            'coverage-shard, junit-shard — the guards below '
