      () {
        for (final retry in retries) {
          expect(
            retry['if']?.toString(),
            contains('always()'),
            reason:
                'the gh-1724 retries must stay reachable after a failed '
                'upload step — without always() GitHub skips every later '
                'step of a failing job and the retry would never fire',
